  const H = {
    dark: '#1b2632', blue: '#2c3b4d', cream: '#eee9df', sand: '#c9c1b1', rust: '#a35139', orange: '#ffb162',
    light: '#ffd7a8', band: '#f39a55', midtone: '#d98049', night: '#6e3424', cheek: '#e8805a'
  };

  function colors(light) {
    return {
      0: H.night, 1: H.rust, 2: H.midtone, 3: H.band, 4: H.orange, 5: H.light,
      o: H.dark, b: H.cream, m: H.dark, g: H.cheek,
      R: light ? H.blue : H.cream, r: light ? H.dark : H.band, q: light ? H.dark : H.sand,
      L: light ? H.blue : H.cream, l: light ? H.dark : H.sand
    };
  }

  function isLightNow() {
    const t = document.documentElement.dataset.theme;
    if (t) return t === 'light';
    return !!(window.matchMedia && matchMedia('(prefers-color-scheme: light)').matches);
  }

  function icon(cv, side, options) {
    options = options || {};
    const I = ICONS[side];
    if (!I) throw new Error('Orbi.icon: supported sizes are 16, 32, and 64');
    const g = cv.getContext('2d');
    const draw = (k) => {
      const light = options.theme ? options.theme === 'light' : isLightNow();
      const c = colors(light), f = I.frames[k];
      g.clearRect(0, 0, side, side);
      for (let y = 0; y < side; y++) for (let x = 0; x < side; x++) {
        const col = c[f[y][x]];
        if (col) { g.fillStyle = col; g.fillRect(x, y, 1, 1); }
      }
    };
    const reducedMotion = window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches;
    if (!options.animate || reducedMotion) { draw(options.frame || 0); return () => {}; }
    let i = 0, timer = 0, alive = true;
    const loop = () => {
      if (!alive) return;
      const [k, ms] = I.sequence[i];
      draw(k);
      i = (i + 1) % I.sequence.length;
      timer = setTimeout(loop, ms);
    };
    loop();
    return () => { alive = false; clearTimeout(timer); };
  }

  if (!window.Orbi) window.Orbi = {};
  window.Orbi.ICONS = ICONS;
  window.Orbi.icon = icon;
  window.Orbi.iconColors = colors;
